package org.springframework.samples.petclinic.acceptance;

import java.time.DayOfWeek;
import java.time.LocalDate;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import tools.jackson.databind.node.ObjectNode;

/** business-day: the effective registration date must fall on a business day (a weekend rolls
 * forward to Monday). Can't force the server's clock black-box, so assert the invariant that holds
 * every day: the default registrationDate is never a Saturday or Sunday. A SUPPLIED weekend date is
 * rolled forward too, and values derived from the registration date use the adjusted date. */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreDefaultDateIsBusinessDay() throws Exception {
		int id = createOwnerOk(ownerNode());
		DayOfWeek dow = LocalDate.parse(fetchOwner(id).get("registrationDate").asText()).getDayOfWeek();
		assertTrue(dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY, dow.toString());
	}

	@Test
	void suppliedSaturdayRollsForwardToMonday() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2030-06-15"); // a Saturday
		assertEquals("2030-06-17", fetchOwner(createOwnerOk(o)).get("registrationDate").asText());
	}

	@Test
	void suppliedSundayRollsForwardToMonday() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2030-06-16"); // a Sunday
		assertEquals("2030-06-17", fetchOwner(createOwnerOk(o)).get("registrationDate").asText());
	}

	@Test
	void suppliedBusinessDayIsUnchanged() throws Exception {
		ObjectNode o = ownerNode();
		o.put("registrationDate", "2030-06-18"); // a Wednesday
		assertEquals("2030-06-18", fetchOwner(createOwnerOk(o)).get("registrationDate").asText());
	}

	@Test
	void membershipNumberYearUsesAdjustedDate() throws Exception {
		// Rolling a 31 Dec 2027 (Friday? no — a weekend) forward can cross a year boundary; here the
		// year segment must come from the ADJUSTED Monday's year, not the supplied weekend date.
		ObjectNode o = ownerNode();
		o.put("city", "Sydney"); // pinned city so a customerCode/membershipNumber is produced
		o.put("registrationDate", "2030-06-15"); // Saturday -> Monday 2030-06-17
		String membershipNumber = fetchOwner(createOwnerOk(o)).get("membershipNumber").asText();
		assertTrue(membershipNumber.endsWith("-M30"), membershipNumber);
	}
}

